using System;
using System.Collections;
using UnityEngine;

public static class RendererExtensions
{
	public static void SetAlpha(this Renderer r, float alpha, MaterialPropertyBlock mpb)
	{
		mpb.SetFloat("_Alpha", alpha);
		r.SetPropertyBlock(mpb);
	}

	public static IEnumerator FadeSprite(this Renderer r, MaterialPropertyBlock mpb, float targetAlpha, float duration, AnimationCurve curve)
	{
		float startingAlpha = mpb.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			r.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v), mpb);
		});
	}

	public static IEnumerator FadeSprite(this Renderer r, MaterialPropertyBlock mpb, float targetAlpha, float duration, AnimationCurve curve, bool isRealtime)
	{
		float startingAlpha = mpb.Alpha();
		return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			r.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v), mpb);
		}, isRealtime);
	}

