	public static IEnumerator BlinkRenderer(this Renderer r, MaterialPropertyBlock mpb, float targetAlpha, float duration, int cycles)
	{
		float startingAlpha = mpb.Alpha();
		AnimationCurve curve = new AnimationCurve();
		curve.AddKey(0f, 0f);
		curve.AddKey(0.5f, 1f);
		curve.AddKey(1f, 0f);
		for (int i = 0; i < cycles; i++)
		{
			yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
			{
				r.SetAlpha(Mathf.Lerp(startingAlpha, targetAlpha, v), mpb);
			});
		}
	}

	public static IEnumerator BlinkRendererWithDelayToStartEffect(this Renderer r, MaterialPropertyBlock mpb, float startingAlpha, float targetAlpha, float duration, int cycles, float delay = 0.2f)
	{
		yield return new WaitForSeconds(delay);
		yield return r.BlinkRenderer(mpb, startingAlpha, targetAlpha, duration, cycles);
	}

