	public static IEnumerator TweenFadeRendererFloat(this Renderer r, MaterialPropertyBlock mpb, string propertyName, float startingValue, float targetValue, float duration)
	{
		AnimationCurve animationCurve = new AnimationCurve();
		animationCurve.AddKey(0f, 0f);
		animationCurve.AddKey(1f, 1f);
		return r.TweenFadeRendererFloat(mpb, propertyName, startingValue, targetValue, duration, animationCurve);
	}

	public static IEnumerator TweenFadeRendererFloat(this Renderer r, MaterialPropertyBlock mpb, string propertyName, float startingValue, float targetValue, float duration, AnimationCurve curve)
	{
		yield return CoroutineUtility.CurveRoutine(duration, curve, delegate(float t, float v)
		{
			r.SetRendererFloat(mpb, propertyName, Mathf.Lerp(startingValue, targetValue, v));
		});
	}

	public static void SetRendererColor(this Renderer r, MaterialPropertyBlock mpb, Color color)
	{
		mpb.SetColor("_Color", color);
		r.SetPropertyBlock(mpb);
	}

	public static void SetRendererFloat(this Renderer r, MaterialPropertyBlock mpb, string propertyName, float value)
	{
		mpb.SetFloat(propertyName, value);
		r.SetPropertyBlock(mpb);
	}

	public static void SetRendererInt(this Renderer r, MaterialPropertyBlock mpb, string propertyName, int value)
	{
		mpb.SetInt(propertyName, value);
		r.SetPropertyBlock(mpb);
	}

	public static float Alpha(this MaterialPropertyBlock mpb)
	{
		return mpb.GetFloat("_Alpha");
	}
